<?php

// ==========================================
// 1. BASIC VALIDATION FUNCTIONS
// ==========================================

function isServiceAdmin() {
    // Strict server-side check for userid 2 and 13
    if (isset($_SESSION['userid'])) {
        $id = (int)$_SESSION['userid'];
        return ($id === 2 || $id === 13);
    }
    return false;
}

// ===============================================================================
//    Prepares a string for CSV: handles NULLs and protects the ", " sequence
// ===============================================================================

function cleanForCsv($val) {
    if ($val === null || $val === "") return "-";
    // Specifically protect the ", " string so it doesn't break the CSV columns
    return str_replace('", "', '[[COMMA_SPACE]]', $val);
}


function emptyInputSignup($name, $email, $username, $pwd, $pwdRepeat) {
    // 1. Initial check for empty values
    if (empty($name) || empty($email) || empty($username) || empty($pwd) || empty($pwdRepeat)) {
        return true;
    }

    // 2. Check Name: at least 2 chars + space + any content + at least 2 chars at end
    $cleanName = str_replace('.', '', $name); 
    // This allows "Teun van Sambeek" while requiring 2 chars min on both outer ends
    if (!preg_match('/^[^\s]{2,}\s+.*[^\s]{2,}$/', $cleanName)) {
        return true;
    }

    // 3. Check Email length and illegal characters
    if (strlen($email) < 6 || strpos($email, "<") !== false || strpos($email, ">") !== false) {
        return true;
    }

    // 4. Check Username: at least 4 chars, only a-z, A-Z, and _
    if (!preg_match('/^[a-zA-Z0-9_]{4,}$/', $username)) {
        return true;
    }

    // 5. Password Strength Check
    $passwordRegex = '/^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[!@#$%^&*()_+\-=\[\]{};\':"\\|,.<>\/?]).{8,}$/';
    if (!preg_match($passwordRegex, $pwd)) {
        return true;
    }

    return false;
}



function emptyInputProfile($name, $email, $username) {
    // 1. Initial check for empty values
    if (empty($name) || empty($email) || empty($username)) {
        return true;
    }

    // 2. Check Name: at least 2 chars + space + any content + at least 2 chars at end
    $cleanName = str_replace('.', '', $name);
    // Updated Regex: allows multiple spaces/words
    if (!preg_match('/^[^\s]{2,}\s+.*[^\s]{2,}$/', $cleanName)) {
        return true;
    }

    // 3. Check Email length and illegal characters
    if (strlen($email) < 6 || strpos($email, "<") !== false || strpos($email, ">") !== false) {
        return true;
    }

    // 4. Check Username: at least 4 chars, only a-z, A-Z, and _
    if (!preg_match('/^[a-zA-Z0-9_]{4,}$/', $username)) {
        return true;
    }

    return false;
}



function invalidUid($username) {
    // Allows letters, numbers, and underscores
    if (!preg_match("/^[a-zA-Z0-9_]*$/", $username)) {
        return true;
    }
    return false;
}


function invalidEmail($email) {
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return true;
    }
    return false;
}


function pwdMatch($pwd, $pwdRepeat) {
    return ($pwd !== $pwdRepeat);
}


function uidExists($conn, $username, $email) {
    $sql = "SELECT * FROM users WHERE usersUid = ? OR usersEmail = ?;";
    $stmt = mysqli_stmt_init($conn);
    if (!mysqli_stmt_prepare($stmt, $sql)) return false;

    mysqli_stmt_bind_param($stmt, "ss", $username, $email);
    mysqli_stmt_execute($stmt);

    // UNIVERSAL FETCH: Works on all servers
    $meta = mysqli_stmt_result_metadata($stmt);
    $params = [];
    $row = [];
    while ($field = mysqli_fetch_field($meta)) {
        $params[] = &$row[$field->name];
    }
    call_user_func_array([$stmt, 'bind_result'], $params);

    if (mysqli_stmt_fetch($stmt)) {
        $userData = [];
        foreach ($row as $key => $val) { $userData[$key] = $val; }
        mysqli_stmt_close($stmt);
        return $userData;
    }
    mysqli_stmt_close($stmt);
    return false;
}


function invalidInput(...$inputs) {
    // This (...$inputs) catches everything you pass to the function into one array
    foreach ($inputs as $input) {
        // Only check if the input is not empty to avoid errors
        if (!empty($input)) {
            if (strip_tags($input) !== $input) {
                return true;
            }
        }
    }
    return false;
}



// SHA256 Verification of the User Data
function verifyIntegrity($userData) {
    $dataToHash = (string)$userData['usersName'] . (string)$userData['image'] . 
                  (string)$userData['birthday'] . (string)$userData['gender'] . 
                  (string)$userData['height'] . (string)$userData['hair'] . 
                  (string)$userData['leftEye'] . (string)$userData['rightEye'] . 
                  (string)$userData['specialFeatures'] . (string)$userData['start'] . 
                  (string)$userData['lastHash'];

    $checkHash = hash('sha256', $dataToHash);
    return ($userData['hash'] === $checkHash);
}


