function invalidBirthday($birthday) {
    $birthDate = DateTime::createFromFormat('Y-m-d', $birthday);
    $today = new DateTime('today');
    if (!$birthDate || $birthDate->format('Y') <= 1900 || $birthDate >= $today) {
        return true;
    }
    return false;
}


function checkHeight($c_height, &$meter = "", &$feetinch = "") {
    $c_height = str_replace(',', '.', $c_height);
    $meter = "";
    $feetinch = "";
    $c_height = trim($c_height);
    $tempMeter = "";

    // 1. Check for Meter pattern (e.g., 1.80m)
    if (preg_match('/(\d+(?:[.,]\d{1,2})?)\s*(?:meter|m)?\b/i', $c_height, $mMatches)) {
        $val = (float)str_replace(',', '.', $mMatches[1]);
        if ($val >= 0.20 && $val < 3.00) {
            $tempMeter = number_format($val, 2, '.', '') . 'm';
        }
    }

    $feetRegex = "/(f|ft|F|FT|Ft|Feet|feet|FEET|')/i";
    $inchRegex = "/(i|in|I|IN|In|Inch|inch|INCH|\")/i";
    $hasFeetInchUnits = preg_match($feetRegex, $c_height) || preg_match($inchRegex, $c_height);

    if ($hasFeetInchUnits) {
        $meter = ""; 
        $fPattern = '(\d+)\s*(?:f|ft|F|FT|Ft|Feet|feet|FEET|\')';
        $iPattern = '(?:\s*(\d+)\s*(?:i|in|I|IN|In|Inch|inch|INCH|")?)?';
        
        if (preg_match("/$fPattern$iPattern/i", $c_height, $fiMatches)) {
            $f = (int)$fiMatches[1];
            $i = isset($fiMatches[2]) ? (int)$fiMatches[2] : 0;
            if ($f >= 1 && $f < 10 && $i >= 0 && $i < 12) {
                $feetinch = ($i == 0) ? $f . "ft" : $f . "ft " . $i . "in";
                $meter = ""; 
            } else {
                $feetinch = "";
                $meter = $tempMeter;
            }
        } else {
            $feetinch = "";
            $meter = $tempMeter;
        }
    } else {
        // NO UNITS DETECTED (No 'm', 'ft', 'in', etc.)
        $meter = $tempMeter;

        // If no units were used, analyze the raw numeric value
        if ($meter === "" && preg_match('/^(\d+)(?:[.\s](\d+))?$/', $c_height, $numMatches)) {
            $val1 = (int)$numMatches[1];
            $val2 = isset($numMatches[2]) ? (int)$numMatches[2] : 0;
            
            // Reconstruct as a decimal for meter comparison
            $decimalVal = (float)($val1 . '.' . $val2);

            if ($decimalVal >= 0.3 && $decimalVal < 3.0) {
                // Assume Meters (e.g., 1.8 becomes 1.80m)
                $meter = number_format($decimalVal, 2, '.', '') . 'm';
                $feetinch = "";
            } elseif ($val1 >= 3 && $val1 <= 9 && $val2 < 12) {
                // Assume Feet/Inches (e.g., 5.11 becomes 5ft 11in)
                $feetinch = ($val2 == 0) ? $val1 . "ft" : $val1 . "ft " . $val2 . "in";
                $meter = ""; 
            }
        }
    }
    return ($meter === "" && $feetinch === "");
}


function invalidHeight($height) {
    $m = ""; 
    $fi = "";
    return checkHeight($height, $m, $fi);
}



function invalidImage($image) {
    $base64Data = preg_replace('#^data:image/\w+;base64,#i', '', $image);
    
    // At 140x140, a real photo is rarely under 5000 characters.
    if (strlen($base64Data) < 4000) return true; 

    $imageData = base64_decode($base64Data);
    $src = @imagecreatefromstring($imageData);
    if (!$src) return true;

    // 1. UNIQUE COLOR COUNT (Detects Cartoons/Icons)
    $colors = [];
    // Since it's only 140x140, we can sample more points quickly
    for ($x = 0; $x < 140; $x += 4) {
        for ($y = 0; $y < 140; $y += 4) {
            $colors[] = imagecolorat($src, $x, $y);
        }
    }
    $uniqueColorCount = count(array_unique($colors));

    // 2. BRIGHTNESS & CONTRAST (Sampling 5 points)
    $points = [
        imagecolorat($src, 70, 70),   // Center
        imagecolorat($src, 30, 30),   // Corners
        imagecolorat($src, 110, 30),  
        imagecolorat($src, 30, 110),  
        imagecolorat($src, 110, 110)  
    ];
    $brightnesses = [];
    foreach ($points as $rgb) {
        $brightnesses[] = ((($rgb >> 16) & 0xFF) + (($rgb >> 8) & 0xFF) + ($rgb & 0xFF)) / 3;
    }
    $avgBrightness = array_sum($brightnesses) / count($brightnesses);
    $variance = max($brightnesses) - min($brightnesses);

    imagedestroy($src);

    // REJECT IF:
    // - Too few colors (Symbol/Cartoon)
    // - Too dark (avg < 25) or too bright (avg > 230)
    // - Too "flat" (variance < 30 - likely a single color or very low contrast)
    if ($uniqueColorCount < 400 || $avgBrightness < 25 || $avgBrightness > 230 || $variance < 30) {
        return true;
    }
    return false;
}


