// ======================================================================================
// Checks if a user has historical records and returns button details and formatted date.
// ======================================================================================

function getProfileFooterData($conn, $userId, $rawDate) {
    // Format Date using your translated months
    if (!empty($rawDate)) {
        $timestamp = strtotime($rawDate);
        $day = date("d", $timestamp);
        $year = date("Y", $timestamp);
        $monthKey = 'M_' . date("n", $timestamp);
        $monthTranslation = t($monthKey);
        
        // Ensure we get the string if t() returns an array
        $translatedMonth = is_array($monthTranslation) ? $monthTranslation[0] : $monthTranslation;
        $formattedDate = $day . " " . $translatedMonth . " " . $year;
    } else {
        $formattedDate = "00 --- 0000";
    }

    // Check for history
    $sql = "SELECT uid_old FROM users_old WHERE uid_old = ? LIMIT 1;";
    $stmt = mysqli_stmt_init($conn);
    $hasHistory = false;

    if (mysqli_stmt_prepare($stmt, $sql)) {
        mysqli_stmt_bind_param($stmt, "i", $userId);
        mysqli_stmt_execute($stmt);
        $result = mysqli_stmt_get_result($stmt);
        if (mysqli_fetch_assoc($result)) {
            $hasHistory = true;
        }
        mysqli_stmt_close($stmt);
    }

    return [
        'date' => $formattedDate,
        'hasHistory' => $hasHistory,
        'historyText' => t('BTN_HISTORY'),
        'historyUrl' => "humandetails.php?id=" . $userId
    ];
}


