function calculateUserBalance($conn, $userId) {
    // 1. Fetch the oldest possible start date from both tables
    $sqlDate = "SELECT MIN(join_date) as joined FROM (
                    SELECT start as join_date FROM users WHERE usersId = ?
                    UNION ALL
                    SELECT start_old as join_date FROM users_old WHERE uid_old = ?
                ) as combined_dates";
    
    $stmtD = $conn->prepare($sqlDate);
    $stmtD->bind_param("ii", $userId, $userId);
    $stmtD->execute();
    $dateData = $stmtD->get_result()->fetch_assoc();
    
    if (!$dateData || !$dateData['joined']) return 0.0;

    $trueJoinedDate = $dateData['joined'];
    $decayRate = 0.99995;
    $currentBalance = 1000.0; 
    
    // Normalize START time to the top of the hour
    $lastProcessedTime = date('Y-m-d H:00:00', strtotime($trueJoinedDate));
    $nowNormalized = date('Y-m-d H:00:00');

    // 2. Fetch all transactions for this user
    $sqlT = "SELECT amount, time_stamp, giver, receiver FROM transactions 
             WHERE (giver = ? OR receiver = ?) 
             ORDER BY time_stamp ASC";
    $stmtT = $conn->prepare($sqlT);
    $stmtT->bind_param("ii", $userId, $userId);
    $stmtT->execute();
    $history = $stmtT->get_result();

    while ($row = $history->fetch_assoc()) {
        $thisTime = date('Y-m-d H:00:00', strtotime($row['time_stamp']));
        $diffSeconds = strtotime($thisTime) - strtotime($lastProcessedTime);
        $hours = ($diffSeconds > 0) ? floor($diffSeconds / 3600) : 0;

        if ($hours > 0) {
            $currentBalance *= pow($decayRate, $hours);
            $income = ($decayRate * (1 - pow($decayRate, $hours))) / (1 - $decayRate);
            $currentBalance += $income;
        }

        if ($row['giver'] == $userId) {
            $currentBalance -= (float)$row['amount'];
        } else {
            $currentBalance += (float)$row['amount'];
        }
        $lastProcessedTime = $thisTime;
    }

    // 3. Final Step: Decay from last transaction until NOW
    $finalDiffSeconds = strtotime($nowNormalized) - strtotime($lastProcessedTime);
    $finalHours = ($finalDiffSeconds > 0) ? floor($finalDiffSeconds / 3600) : 0;

    if ($finalHours > 0) {
        $currentBalance *= pow($decayRate, $finalHours);
        $finalIncome = ($decayRate * (1 - pow($decayRate, $finalHours))) / (1 - $decayRate);
        $currentBalance += $finalIncome;
    }

    return $currentBalance;
}

function getPreviousTransactionState($conn, $userId, $targetTimestamp) {
    // 1. THE GENESIS FIX: Get the absolute oldest start date from both tables
    $sqlDate = "SELECT MIN(join_date) as joined FROM (
                    SELECT start as join_date FROM users WHERE usersId = ?
                    UNION ALL
                    SELECT start_old as join_date FROM users_old WHERE uid_old = ?
                ) as combined_dates";
    $stmtD = $conn->prepare($sqlDate);
    $stmtD->bind_param("ii", $userId, $userId);
    $stmtD->execute();
    $dateData = $stmtD->get_result()->fetch_assoc();
    
    $trueJoinedDate = $dateData['joined'];
    $currentBalance = 1000.0; 
    $decayRate = 0.99995;
    
    // Normalize TRUE START time to the top of the hour
    $lastProcessedTime = date('Y-m-d H:00:00', strtotime($trueJoinedDate));

    // 2. Fetch all transactions BEFORE the target one
    $sqlT = "SELECT amount, time_stamp, giver, receiver FROM transactions 
             WHERE (giver = ? OR receiver = ?) 
             AND time_stamp < ? 
             ORDER BY time_stamp ASC";
    $stmtT = $conn->prepare($sqlT);
    $stmtT->bind_param("iis", $userId, $userId, $targetTimestamp);
    $stmtT->execute();
    $history = $stmtT->get_result();

    while ($row = $history->fetch_assoc()) {
        $thisTime = date('Y-m-d H:00:00', strtotime($row['time_stamp']));
        $diffSeconds = strtotime($thisTime) - strtotime($lastProcessedTime);
        $hours = ($diffSeconds > 0) ? floor($diffSeconds / 3600) : 0; 

        if ($hours > 0) {
            $currentBalance = $currentBalance * pow($decayRate, $hours);
            $income = ($decayRate * (1 - pow($decayRate, $hours))) / (1 - $decayRate);
            $currentBalance += $income;
        }

        if ($row['giver'] == $userId) {
            $currentBalance -= (float)$row['amount'];
        } else {
            $currentBalance += (float)$row['amount'];
        }
        
        $lastProcessedTime = $thisTime;
    }

    // 3. FINAL STEP: Calculate gap from last event (Join or Prev Transaction) to TARGET
    $finalTargetTime = date('Y-m-d H:00:00', strtotime($targetTimestamp));
    $finalDiffSeconds = strtotime($finalTargetTime) - strtotime($lastProcessedTime);
    $finalHours = ($finalDiffSeconds > 0) ? floor($finalDiffSeconds / 3600) : 0; 

    $reductionFactor = pow($decayRate, $finalHours);
    // Reduction is the amount lost during the wait time
    $reductionAmount = $currentBalance * (1 - $reductionFactor);
    
    if ($finalHours > 0) {
        $oneCoinPerHour = ($decayRate * (1 - pow($decayRate, $finalHours))) / (1 - $decayRate);
    } else {
        $oneCoinPerHour = 0.0;
    }

    // Balance right before the target transaction executes
    $availableBalance = ($currentBalance * $reductionFactor) + $oneCoinPerHour;

    return [
        'previousBalance'  => $currentBalance,
        'hours'            => $finalHours,
        'reductionFactor'  => $reductionFactor,
        'reductionAmount'  => -$reductionAmount, // Negative to show it's a loss
        'income'           => $oneCoinPerHour,
        'availableBalance' => $availableBalance
    ];
}


// Counting Pending Proposals (Limit Check)
function countPendingProposals($conn, $userId) {
    $sql = "SELECT COUNT(pid) as total FROM proposals WHERE giver = ? OR receiver = ?;";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("ii", $userId, $userId);
    $stmt->execute();
    $result = $stmt->get_result();
    $data = $result->fetch_assoc();
    return $data['total'];
}


function sendProposalEmails($giverData, $myData, $amount, $description) {
    global $translations;
    
    // 1. Determine Recipients' Preferences
    // Only the person RECEIVING the email controls if it is sent.
    $giverWantsToReceive = isset($giverData['paymentEmails']) && (int)$giverData['paymentEmails'] === 1;
    $meWantToReceive = isset($myData['paymentEmails']) && (int)$myData['paymentEmails'] === 1;

    // Determine languages
    $langGiver = $giverData['language'] ?? 'en';
    $langMe = $myData['language'] ?? 'en';

    $tr = function($key, $lang) use ($translations) {
        return $translations[$lang][$key] ?? $translations['en'][$key] ?? $key;
    };

    $whitelist = array('127.0.0.1', '::1');
    $isLocalhost = in_array($_SERVER['REMOTE_ADDR'], $whitelist);
    if ($isLocalhost) return true;

    $formattedAmount = number_format($amount, 2) . " ᕫ";
    $headers = "From: Abundomy Money <info@1coinh.com>\r\n";
    $headers .= "Reply-To: info@1coinh.com\r\n";
    $headers .= "MIME-Version: 1.0\r\n";
    $headers .= "Content-Type: text/html; charset=UTF-8\r\n";
    $abundomyLink = '<a href="https://abundomy.com">Abundomy.com</a>';

    $mail1 = true;
    $mail2 = true;

    // --- EMAIL 1: SENT TO THE GIVER ---
    // Controlled by the Giver's preference
    if ($giverWantsToReceive) {
        $subjectGiver = $tr('EM_G_SUBJ', $langGiver) . " " . $myData['usersName'];
        $msgGiver = '<html><body>';
        $msgGiver .= '<p>' . $tr('EM_HELLO', $langGiver) . ' ' . htmlspecialchars($giverData['usersName']) . ',</p>';
        $msgGiver .= '<p><b>' . htmlspecialchars($myData['usersName']) . '</b> ' . $tr('EM_G_BODY', $langGiver) . '</p>';
        $msgGiver .= '<p><b>' . $tr('EM_LBL_AMT', $langGiver) . ':</b> ' . $formattedAmount . '<br>';
        $msgGiver .= '<b>' . $tr('EM_LBL_DESC', $langGiver) . ':</b> ' . htmlspecialchars($description) . '</p>';
        $msgGiver .= '<p>' . sprintf($tr('EM_G_LINK', $langGiver), '<a href="https://1coinh.com">://1coinh.com</a>') . '</p>';
        $footerGiver = str_replace('abundomy.com', $abundomyLink, $tr('EM_FOOTER', $langGiver));
        $msgGiver .= '<br><p>' . $footerGiver . '</p></body></html>';
        
        $mail1 = mail($giverData['usersEmail'], $subjectGiver, $msgGiver, $headers);
    }

    // --- EMAIL 2: SENT TO THE RECEIVER (ME) ---
    // Controlled by My preference
    if ($meWantToReceive) {
        $subjectMe = $tr('EM_M_SUBJ', $langMe) . " " . $giverData['usersName'];
        $msgMe = '<html><body>';
        $msgMe .= '<p>' . $tr('EM_HELLO', $langMe) . ' ' . htmlspecialchars($myData['usersName']) . ',</p>';
        $msgMe .= '<p>' . $tr('EM_M_BODY_1', $langMe) . ' <b>' . htmlspecialchars($giverData['usersName']) . '</b>.</p>';
        $msgMe .= '<p><b>' . $tr('EM_LBL_AMT', $langMe) . ':</b> ' . $formattedAmount . '<br>';
        $msgMe .= '<b>' . $tr('EM_LBL_DESC', $langMe) . ':</b> ' . htmlspecialchars($description) . '</p>';
        $msgMe .= '<p>' . $tr('EM_M_BODY_2', $langMe) . '</p>';
        $footerMe = str_replace('abundomy.com', $abundomyLink, $tr('EM_FOOTER', $langMe));
        $msgMe .= '<br><p>' . $footerMe . '</p></body></html>';
        
        $mail2 = mail($myData['usersEmail'], $subjectMe, $msgMe, $headers);
    }
    return ($mail1 && $mail2);
}


// Standardized Coin Calculation (Decay + Series)
function calculateAvailableCoins($conn, $userId) {
    $userData = getUserData($conn, $userId);
    if (!$userData) return 0;

    // Own coins calculation
    $date0 = new DateTime($userData['joined']);
    $date1 = new DateTime();
    $diff = $date1->diff($date0);
    $hours = ($diff->days * 24) + $diff->h;
    $r = 0.99995;
    $powN = pow($r, $hours);
    $owncoin = (1000 * $powN) + ((1 - $powN) / (1 - $r));

    // Transaction decay calculation
    $spent = 0; $received = 0;
    $sql = "SELECT giver, receiver, amount, time_stamp FROM transactions WHERE receiver = ? OR giver = ?";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("ii", $userId, $userId);
    $stmt->execute();
    $result = $stmt->get_result();
    
    while ($row = $result->fetch_assoc()) {
        $tDate = new DateTime($row["time_stamp"]);
        $tHours = ($date1->diff($tDate)->days * 24) + $date1->diff($tDate)->h;
        $tDecay = (float)$row["amount"] * pow(0.99995, $tHours);
        
        if ($row["giver"] == $userId) { $spent += $tDecay; } 
        else { $received += $tDecay; }
    }
    return ($owncoin + $received - $spent);
}


function getProposalData($conn, $pid) {
    $sql = "SELECT * FROM proposals WHERE pid = ?;";
    $stmt = mysqli_stmt_init($conn);
    if (!mysqli_stmt_prepare($stmt, $sql)) {
        return false;
    }
    mysqli_stmt_bind_param($stmt, "i", $pid);
    mysqli_stmt_execute($stmt);
    $result = mysqli_stmt_get_result($stmt);
    
    if ($row = mysqli_fetch_assoc($result)) {
        mysqli_stmt_close($stmt);
        return $row;
    } else {
        mysqli_stmt_close($stmt);
        return false;
    }
}


// Fetch the most recent transaction for a specific user to anchor the hash
function getLastUserTransaction($conn, $userId) {
    $sql = "SELECT hashgiver, hashreceiver FROM transactions WHERE giver = ? OR receiver = ? ORDER BY tid DESC LIMIT 1";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("ii", $userId, $userId);
    $stmt->execute();
    return $stmt->get_result()->fetch_assoc();
}


// Basic deletion helper
function deleteProposal($conn, $pid) {
    $sql = "DELETE FROM proposals WHERE pid = ?;";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("i", $pid);
    $stmt->execute();
    mysqli_stmt_close($stmt);
}


// Generates Profile History CSV content as a string for the database
function getUserCSVString($conn, $userId) {
    // Open a memory stream instead of a physical file
    $output = fopen('php://temp', 'r+');

    // 1. users_old records
    $sqlOld = "SELECT uid_old, usersName_old, image_old, birthday_old, gender_old, height_old, hair_old, leftEye_old, rightEye_old, specialFeatures_old, start_old, usersOldId, hash_old FROM users_old WHERE uid_old = ? ORDER BY start_old ASC";
    $stmt = $conn->prepare($sqlOld);
    $stmt->bind_param("i", $userId);
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) { 
        fputcsv($output, $row); 
    }

    // 2. Current users record
    $sqlCurr = "SELECT usersId, usersName, image, birthday, gender, height, hair, leftEye, rightEye, specialFeatures, start, lastHash, hash FROM users WHERE usersId = ?";
    $stmt2 = $conn->prepare($sqlCurr);
    $stmt2->bind_param("i", $userId);
    $stmt2->execute();
    $curr = $stmt2->get_result()->fetch_assoc();
    if ($curr) {
        fputcsv($output, $curr);
    }

    rewind($output);
    $csvString = stream_get_contents($output);
    fclose($output);
    return $csvString;
}


// Generates Transaction History CSV content as a string for the database
function getTransactionCSVString($conn, $userId) {
    $output = fopen('php://temp', 'r+');

    $sql = "SELECT tid, giver, receiver, amount, description, time_stamp, hashgiver, hashreceiver FROM transactions WHERE giver = ? OR receiver = ? ORDER BY time_stamp ASC";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param("ii", $userId, $userId);
    $stmt->execute();
    $res = $stmt->get_result();
    while ($row = $res->fetch_assoc()) { 
        fputcsv($output, $row); 
    }

    rewind($output);
    $csvString = stream_get_contents($output);
    fclose($output);
    return $csvString;
}


function sendDeletionEmail($pData, $reason) {
    global $translations;
    $isLocalhost = in_array($_SERVER['REMOTE_ADDR'], ['127.0.0.1', '::1']);
    if ($isLocalhost) return true;

    $giverData = getUserData($GLOBALS['conn'], $pData['giver']);
    $receiverData = getUserData($GLOBALS['conn'], $pData['receiver']);
    
    // Helper to get translation
    $tr = function($key, $lang) use ($translations) {
        return $translations[$lang][$key] ?? $translations['en'][$key] ?? $key;
    };

    $headers = "From: Abundomy Money <info@1coinh.com>\r\n";
    $headers .= "MIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\n";

    $users = [$giverData, $receiverData];

    foreach ($users as $user) {
        // --- PREFERENCE CHECK ---
        // Only send if the recipient has paymentEmails enabled (set to 1)
        if (!isset($user['paymentEmails']) || (int)$user['paymentEmails'] !== 1) {
            continue; // Skip this user and move to the next one
        }

        $lang = $user['language'] ?? 'en';
        $to = $user['usersEmail'];
        $subject = $tr('DL_SUBJECT', $lang);

        if ($user['usersId'] == $giverData['usersId']) {
            $partnerLabel = $tr('DL_FOR', $lang) . ": " . htmlspecialchars($receiverData['usersName']);
        } else {
            $partnerLabel = $tr('DL_FROM', $lang) . ": " . htmlspecialchars($giverData['usersName']);
        }

        // Define the clickable link for the footer
        $abundomyLink = '<a href="https://abundomy.com">Abundomy.com</a>';

        $message = '<html><body>';
        $message .= '<p>' . $tr('DL_HELLO', $lang) . ' ' . htmlspecialchars($user['usersName']) . ',</p>';
        $message .= '<p>' . sprintf($tr('DL_BODY', $lang), '<b>' . number_format($pData['amount'], 2) . ' ᕫ</b>') . '</p>';
        $message .= '<p><b>' . $partnerLabel . '</b></p>';
        $message .= '<p><b>' . $tr('DL_REASON', $lang) . ':</b> ' . htmlspecialchars($reason) . '</p>';
        $message .= '<p><b>' . $tr('DL_DESC', $lang) . ':</b> ' . htmlspecialchars($pData['description']) . '</p>';
        
        // Inject link into the Deletion Email footer
        $footerLink = str_replace('abundomy.com', $abundomyLink, $tr('DL_FOOTER', $lang));
        $message .= '<br><p>' . $footerLink . '</p>';
        $message .= '</body></html>';

        mail($to, $subject, $message, $headers);
    }
    return true;
}




function sendPaymentEmail($pData) {
    global $translations;
    $isLocalhost = in_array($_SERVER['REMOTE_ADDR'], ['127.0.0.1', '::1']);
    if ($isLocalhost) return true;

