function loginuser($conn, $username, $pwd) {
    $userData = uidExists($conn, $username, $username);
    if ($userData === false) {
        header("location: ../index2.php?error=wronglogin");
        exit();
    }

    if (!password_verify($pwd, $userData["usersPwd"])) {
        header("location: ../index2.php?error=wronglogin");
        exit();
    }

    // --- INITIALIZE SESSION ---
    $_SESSION["userid"] = $userData["usersId"];
    $_SESSION["useruid"] = $userData["usersUid"];
    $_SESSION["isReceiving"] = true;

    // --- SOFT IDENTITY HASH TEST ---
    // Instead of blocking the login, we flag the session if a mismatch occurs.
    $dataToHash = (string)$userData['usersName'] . 
                  (string)$userData['image'] . 
                  (string)$userData['birthday'] . 
                  (string)$userData['gender'] . 
                  (string)$userData['height'] . 
                  (string)$userData['hair'] . 
                  (string)$userData['leftEye'] . 
                  (string)$userData['rightEye'] . 
                  (string)$userData['specialFeatures'] . 
                  (string)$userData['start'] . 
                  (string)$userData['lastHash'];
    $checkHash = hash('sha256', $dataToHash);


    if ($userData['hash'] !== $checkHash) {
        header("location: ../index2.php?error=hashmismatch");
        exit();
    }

    // if ($userData['hash'] !== $checkHash) {
    //     // Flag the session so the app can display an alert/notice banner to the user
    //     $_SESSION["hash_error"] = true;
    // } else {
    //     $_SESSION["hash_error"] = false;
    // }

    // Check if function exists before calling to prevent 500 error
    if (function_exists('getUserProposals')) {
        getUserProposals($conn, $userData["usersId"]);
    }

    // --- LOGIN LOGGING ---
    $logindate = gmdate('Y-m-d H:i:s');
    $uid = $userData["usersId"];
    $sqlLog = "INSERT INTO loginLog (usersId, login, logout) VALUES (?, ?, ?);";
    $stmtLog = mysqli_stmt_init($conn);
    if (mysqli_stmt_prepare($stmtLog, $sqlLog)) {
        mysqli_stmt_bind_param($stmtLog, "iss", $uid, $logindate, $logindate);
        mysqli_stmt_execute($stmtLog);
        mysqli_stmt_close($stmtLog);
    }

    header("location: ../index2.php?login=success");
    exit();
}


